import type {MedusaRequest,MedusaResponse}from"@medusajs/framework/http";import{ContainerRegistrationKeys}from"@medusajs/framework/utils";
const actor=(r:MedusaRequest)=>(r as any).auth_context?.actor_id||(r as any).auth_context?.auth_identity_id;
async function sid(r:MedusaRequest){const a=actor(r);if(!a)return null;const q=r.scope.resolve(ContainerRegistrationKeys.QUERY)as any;const{data}=await q.graph({entity:"seller_member",fields:["seller.id"],filters:{member_id:a},pagination:{take:1}});return data?.[0]?.seller?.id||null}
async function owns(r:MedusaRequest,seller:string){const q=r.scope.resolve(ContainerRegistrationKeys.QUERY)as any;const{data}=await q.graph({entity:"order",fields:["items.product_id"],filters:{id:r.params.id},pagination:{take:1}});const ids=(data?.[0]?.items||[]).map((x:any)=>x.product_id).filter(Boolean);const sp=r.scope.resolve("spike")as any;const links=ids.length?await sp.listSpikeProductDeliveries({product_id:ids},{take:500}):[];return links.some((x:any)=>x.seller_id===seller)}
export async function GET(req:MedusaRequest,res:MedusaResponse){const seller=await sid(req);if(!seller||!await owns(req,seller))return res.status(403).json({message:"لا تملك صلاحية لهذا الطلب"});const sp=req.scope.resolve("spike")as any;const rows=await sp.listSpikePaymentReceipts({order_id:req.params.id},{take:1,order:{created_at:"DESC"}});res.json({receipt:rows[0]||null})}
export async function POST(req:MedusaRequest,res:MedusaResponse){const seller=await sid(req);if(!seller||!await owns(req,seller))return res.status(403).json({message:"لا تملك صلاحية لهذا الطلب"});const status=String((req.body as any)?.status||"");if(!["approved","rejected"].includes(status))return res.status(400).json({message:"الحالة غير صحيحة"});const sp=req.scope.resolve("spike")as any;const rows=await sp.listSpikePaymentReceipts({order_id:req.params.id},{take:1,order:{created_at:"DESC"}});if(!rows[0])return res.status(404).json({message:"لا يوجد إيصال حوالة لهذا الطلب"});const receipt=await sp.updateSpikePaymentReceipts({id:rows[0].id,status,note:String((req.body as any)?.note||"")});const q=req.scope.resolve(ContainerRegistrationKeys.QUERY)as any;const od=await q.graph({entity:"order",fields:["customer_id"],filters:{id:req.params.id},pagination:{take:1}});const customer=od.data?.[0]?.customer_id;if(customer)await sp.createSpikeNotifications({audience:"customer",customer_id:customer,seller_id:seller,type:"payment_receipt",title:status==="approved"?"تم قبول الحوالة":"تم رفض الحوالة",body:status==="approved"?"تم تأكيد الحوالة وسيتم تجهيز طلبك.":"تعذر اعتماد الحوالة. تواصل مع المتجر للمراجعة.",entity_type:"order",entity_id:req.params.id,read:false});res.json({receipt})}
